contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other) public payable {
        require(other != address(this), "other must not be the test contract");

        uint256 balBefore = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 cBalBefore = address(c).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balAfter = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 cBalAfter = address(c).balance;

        assert(
            reverted ||
            (balBefore == 0 && balAfter == 0) ||
            (other == address(this) && balAfter == 0) ||
            (balBefore != 0 && other != address(this) && (balAfter == 0 || cBalAfter == cBalBefore - balBefore))
        );
    }

    receive() external payable {}
}

